// Seeded value-noise biome map generator. No dependencies.

export const SIZE = 64;

export type Biome = "SNOW" | "DESERT" | "GRASS" | "FOREST";

export interface BiomeMap {
  elevation: Float64Array;
  moisture: Float64Array;
  biomes: Uint8Array; // indices into BIOME_NAMES
  changedByPostPass: number; // cells flipped DESERT -> GRASS by the post-pass
}

export const BIOMES: readonly Biome[] = ["SNOW", "DESERT", "GRASS", "FOREST"] as const;

// ---------------------------------------------------------------------------
// Inline seeded value noise
// ---------------------------------------------------------------------------

/** Deterministic integer hash -> [0, 1). */
function hash2(x: number, y: number, seed: number): number {
  let h = (seed | 0) ^ Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Smoothstep-style quintic fade for interpolation. */
function fade(t: number): number {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

/** Bilinearly interpolated value noise at arbitrary (x, y). */
function valueNoise(x: number, y: number, seed: number): number {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const fx = fade(x - x0);
  const fy = fade(y - y0);

  const v00 = hash2(x0, y0, seed);
  const v10 = hash2(x0 + 1, y0, seed);
  const v01 = hash2(x0, y0 + 1, seed);
  const v11 = hash2(x0 + 1, y0 + 1, seed);

  const top = v00 + (v10 - v00) * fx;
  const bottom = v01 + (v11 - v01) * fx;
  return top + (bottom - top) * fy;
}

/** Fractal Brownian motion over value noise, normalized to ~[0, 1]. */
function fbm(x: number, y: number, seed: number, octaves: number): number {
  let sum = 0;
  let amp = 1;
  let norm = 0;
  let fx = x;
  let fy = y;
  for (let o = 0; o < octaves; o++) {
    sum += amp * valueNoise(fx, fy, seed + o * 1013);
    norm += amp;
    amp *= 0.5;
    fx *= 2;
    fy *= 2;
  }
  return sum / norm;
}

/**
 * Generate a fractal field of SIZE x SIZE samples in [0, 1].
 * The raw fbm output is min-max normalized so the full range is exercised.
 */
function generateField(seed: number, salt: number, scale: number, octaves: number): Float64Array {
  const raw = new Float64Array(SIZE * SIZE);
  let min = Infinity;
  let max = -Infinity;
  for (let y = 0; y < SIZE; y++) {
    for (let x = 0; x < SIZE; x++) {
      const v = fbm(x / scale, y / scale, seed ^ salt, octaves);
      raw[y * SIZE + x] = v;
      if (v < min) min = v;
      if (v > max) max = v;
    }
  }
  const span = max - min || 1;
  for (let i = 0; i < raw.length; i++) raw[i] = (raw[i] - min) / span;
  return raw;
}

// ---------------------------------------------------------------------------
// Classification + post-pass
// ---------------------------------------------------------------------------

const SNOW = 0;
const DESERT = 1;
const GRASS = 2;
const FOREST = 3;

export function classify(elevation: number, moisture: number): number {
  if (elevation > 0.75) return SNOW;
  if (moisture < 0.3) return DESERT;
  if (moisture < 0.65) return GRASS;
  return FOREST;
}

const ORTHO = [
  [-1, 0],
  [1, 0],
  [0, -1],
  [0, 1],
] as const;

/** Flip every DESERT cell orthogonally adjacent to a SNOW cell to GRASS. */
function enforceDesertSnowInvariant(biomes: Uint8Array): number {
  const toFlip: number[] = [];
  for (let y = 0; y < SIZE; y++) {
    for (let x = 0; x < SIZE; x++) {
      if (biomes[y * SIZE + x] !== DESERT) continue;
      for (const [dx, dy] of ORTHO) {
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= SIZE || ny >= SIZE) continue;
        if (biomes[ny * SIZE + nx] === SNOW) {
          toFlip.push(y * SIZE + x);
          break;
        }
      }
    }
  }
  for (const i of toFlip) biomes[i] = GRASS;
  return toFlip.length;
}

// ---------------------------------------------------------------------------

export function generateBiomes(seed: number): BiomeMap {
  const elevation = generateField(seed, 0x9e3779b9, 12, 5);
  const moisture = generateField(seed, 0x51ed270b, 16, 4);
  const biomes = new Uint8Array(SIZE * SIZE);
  for (let i = 0; i < biomes.length; i++) {
    biomes[i] = classify(elevation[i], moisture[i]);
  }
  const changedByPostPass = enforceDesertSnowInvariant(biomes);
  return { elevation, moisture, biomes, changedByPostPass };
}

